import{_ as t,a as l,c as i,ac as r}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"CDN","description":"CDN","frontmatter":{"title":"CDN","description":"CDN","sources":[{"repository":"jekyall_blog","file":"_posts/DevOps/network/2024-04-28-CDN.md","date":"Sun Apr 28 2024 12:48:54 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"network","title":"网络配置与诊断","link":"/topics/network/"},{"id":"cloud","title":"云主机与资源管理","link":"/topics/cloud/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","summary":"CDN","status":"active","related":[{"title":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"网络配置与诊断 操作与命令","link":"/systems/network-remote/network/plus/ecosystem/network-general-general","kind":"命令与对象入口","scope":"general","audience":"general"},{"title":"OSI 与 TCP/IP 分层笔记","link":"/systems/network-remote/network/plus/subjects/networkengineerbase","kind":"知识专题","scope":"general","audience":"general"},{"title":"TCP/IP","link":"/systems/network-remote/network/plus/subjects/tcpip","kind":"知识专题","scope":"general","audience":"general"},{"title":"网络：地址、端口、DNS 与基本观察","link":"/systems/network-remote/network/base/basic/start","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application"},"next":{"text":"ssh 工具","link":"/systems/network-remote/network/plus/subjects/ssh-%E5%B7%A5%E5%85%B7"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application"},"next":{"text":"ssh 工具","link":"/systems/network-remote/network/plus/subjects/ssh-%E5%B7%A5%E5%85%B7"}},"headers":[],"relativePath":"systems/network-remote/network/plus/subjects/cdn.md","filePath":"systems/network-remote/network/plus/subjects/cdn.md"}'),o={name:"systems/network-remote/network/plus/subjects/cdn.md"};function s(a,e,n,c,d,u){return l(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="cdn" tabindex="-1">CDN <a class="header-anchor" href="#cdn" aria-label="Permalink to &quot;CDN&quot;">​</a></h1><h2 id="cdn-1" tabindex="-1">CDN <a class="header-anchor" href="#cdn-1" aria-label="Permalink to &quot;CDN&quot;">​</a></h2><blockquote><p>CDN 是内容分发网络（Content Delivery Network）的缩写。它是一个由分布在全球各地的服务器网络组成的系统，用于在用户请求内容时快速交付网站、应用程序、音频、视频和其他互联网内容</p></blockquote><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><ul><li>网络架构：CDN 由多个位于全球各地的服务器节点组成，这些节点通常称为边缘服务器。这些服务器节点分布在地理位置上的关键位置，以便尽可能地靠近最终用户。</li><li>工作原理：当用户请求访问一个网站或者特定的内容时，CDN 系统会根据网络、负载、健康和调度策略选择合适节点，未必是地理上最近的服务器来提供内容。这样做可以减少数据传输的距离，从而降低延迟和提高加载速度。</li><li>内容缓存：CDN 会将网站的静态内容（如图像、样式表、脚本等）缓存到其服务器节点上。当有用户请求相同内容时，CDN 会直接从缓存中提供，而不是从原始服务器获取，这样可以减轻原始服务器的负载。</li><li>负载均衡：CDN 能够智能地分配流量到其服务器节点，以确保网络负载均衡，避免某个节点过载。</li><li>内容优化：CDN 可以对内容进行优化，包括压缩、图片优化、缓存控制等，以提高传输效率和用户体验。</li><li>安全性：CDN 提供一定程度的安全性，包括 DDoS（分布式拒绝服务攻击）防护、SSL 证书支持等功能，以保护网站免受恶意攻击。</li><li>分布式存储：CDN 可以作为内容的分布式存储解决方案，确保内容的可靠性和高可用性</li></ul><h2 id="原始服务有改变缓存" tabindex="-1">原始服务有改变缓存 <a class="header-anchor" href="#原始服务有改变缓存" aria-label="Permalink to &quot;原始服务有改变缓存&quot;">​</a></h2><ul><li>缓存过期策略：在设置 CDN 时，可以定义缓存内容的过期时间。内容过期后通常需要重新验证或获取；是否允许提供陈旧内容还受响应指令和 CDN 策略约束。你可以根据内容的更新频率和重要性来设置合适的缓存过期策略。</li><li>缓存刷新：当内容发生变化时，你可以手动或自动触发 CDN 的缓存刷新机制，以更新缓存中的内容。这通常可以通过 CDN 提供的管理界面或 API 来完成。</li><li>版本化 URL 或文件名：一种常见的做法是使用版本化的 URL 或文件名来更新内容。每当内容发生变化时，你可以更新 URL 或文件名，这样 CDN 会将其视为新的资源，并在用户请求时获取最新版本。</li><li>Cache-Control 头：通过在原始服务响应的 HTTP 头中包含 Cache-Control 头，可以控制 CDN 对内容的缓存策略。例如，<code>Cache-Control: no-cache</code> 允许存储，但复用前必须向源站成功验证；内容未变时可通过 304 继续使用已存表示，不必重新传完整内容。<code>no-store</code> 才禁止缓存存储。具体 CDN 规则仍须核对产品配置和实际响应，见 <a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.2.4" target="_blank" rel="noopener noreferrer">RFC 9111</a>。</li><li>Purge API：大多数 CDN 提供了 Purge API，允许你针对特定的 URL 或内容进行缓存清除操作，以便立即更新缓存中的内容</li></ul><h2 id="优势-劣势" tabindex="-1">优势/劣势 <a class="header-anchor" href="#优势-劣势" aria-label="Permalink to &quot;优势/劣势&quot;">​</a></h2><ul><li><p>优势</p><ul><li>提高网站性能：CDN 通过将内容缓存在分布式的边缘节点上，使得用户能够从离他们最近的服务器获取内容，从而减少了加载时间和延迟，提高了网站的性能和响应速度。</li><li>提高可用性：由于 CDN 将内容分发到多个服务器上，即使其中一个服务器出现故障，仍然可以从其他服务器获取内容，提高了网站的可用性和稳定性。</li><li>减轻原始服务器负载：CDN 可以缓存静态内容并直接响应用户请求，减轻了原始服务器的负载，提高了网站的承载能力。</li><li>全球覆盖：CDN 的服务器节点分布在全球各地，可以为全球用户提供更快速和稳定的访问体验。</li><li>安全性增强：CDN 提供一些安全功能，如 DDoS 防护、SSL 加密等，有助于保护网站免受网络攻击和数据泄露。</li></ul></li><li><p>劣势</p><ul><li>成本：CDN 服务通常需要支付费用，尤其是对于大型网站或应用来说，这可能是一个显著的成本。</li><li>配置复杂性：对于初学者来说，配置和管理 CDN 可能会有一定的学习曲线，特别是在处理缓存更新和缓存失效时。</li><li>隐私和安全风险：将内容分发到 CDN 可能会引入一些隐私和安全风险，尤其是对于一些敏感数据或个人信息的网站。</li><li>依赖第三方服务：使用 CDN 意味着你的网站依赖于第三方服务提供商，如果服务提供商出现故障或问题，可能会影响到你的网站正常运行。</li><li>可能增加复杂性：在某些情况下，CDN 的引入可能会增加网站的复杂性，特别是在跨地区和动态内容的处理上。</li></ul></li></ul><blockquote><p>综合来看，CDN 在提高网站性能、可用性和安全性方面具有明显的优势，但也需要注意其可能带来的成本和配置管理方面的挑战。</p></blockquote>',10)])])}const C=t(o,[["render",s]]);export{p as __pageData,C as default};
